import math
from typing import Union

import torch
import torchvision.transforms.v2.functional as tvF

from ...image_processing_backends import TorchvisionBackend
from ...image_processing_utils import BatchFeature, get_patch_output_size, select_best_resolution
from ...image_transforms import divide_to_patches, group_images_by_shape, reorder_images
from ...image_utils import (
    IMAGENET_STANDARD_MEAN,
    IMAGENET_STANDARD_STD,
    ChannelDimension,
    ImageInput,
    PILImageResampling,
    SizeDict,
    get_image_size,
)
from ...processing_utils import ImagesKwargs, Unpack
from ...utils import TensorType, auto_docstring


class HyperCLOVAXVisionImageProcessorKwargs(ImagesKwargs, total=False):
    r"""
    image_grid_pinpoints (`list[list[int]]`, *optional*):
        A list of possible resolutions to use for processing high resolution images. The best resolution is selected
        based on the original size of the image. Can be overridden by `image_grid_pinpoints` in the `preprocess`
        method.
    """

    image_grid_pinpoints: list[list[int]]


def build_image_grid_pinpoints(max_num_grids: int, grid_size: int) -> list[list[int]]:
    """Builds every `(height, width)` resolution made of at most `max_num_grids` square grids of side `grid_size`."""
    return [
        [rows * grid_size, cols * grid_size]
        for rows in range(1, max_num_grids + 1)
        for cols in range(1, max_num_grids + 1)
        if rows * cols <= max_num_grids
    ]


def get_global_view_size(image_size: tuple[int, int], size: int) -> SizeDict:
    """Returns the size of an image of size `(height, width)` resized to `size` on its longest side, keeping its aspect ratio."""
    height, width = image_size
    if height >= width:
        return SizeDict(height=size, width=math.ceil(width / height * size))
    return SizeDict(height=math.ceil(height / width * size), width=size)


@auto_docstring
class HyperCLOVAXVisionImageProcessor(TorchvisionBackend):
    model_input_names = ["pixel_values", "image_sizes"]
    valid_kwargs = HyperCLOVAXVisionImageProcessorKwargs
    resample = PILImageResampling.BILINEAR
    image_mean = IMAGENET_STANDARD_MEAN
    image_std = IMAGENET_STANDARD_STD
    size = {"shortest_edge": 378}
    default_to_square = False
    crop_size = {"height": 378, "width": 378}
    do_resize = True
    do_center_crop = True
    do_rescale = True
    do_normalize = True
    do_convert_rgb = True
    do_pad = True
    image_grid_pinpoints = build_image_grid_pinpoints(max_num_grids=9, grid_size=378)

    def __init__(self, **kwargs):
        # The original checkpoints call the grid pinpoints `possible_resolutions`
        if "possible_resolutions" in kwargs:
            kwargs.setdefault("image_grid_pinpoints", kwargs.pop("possible_resolutions"))
        super().__init__(**kwargs)

    @auto_docstring
    def preprocess(
        self, images: ImageInput | list[ImageInput], *args, **kwargs: Unpack[HyperCLOVAXVisionImageProcessorKwargs]
    ) -> BatchFeature:
        return super().preprocess(images, *args, **kwargs)

    def _get_padding_size(self, original_resolution: tuple, target_resolution: tuple):
        """Get padding size for patching (returns list format for tvF.pad)."""
        original_height, original_width = original_resolution
        target_height, target_width = target_resolution
        paste_x, r_x = divmod(target_width - original_width, 2)
        paste_y, r_y = divmod(target_height - original_height, 2)
        return [paste_x, paste_y, paste_x + r_x, paste_y + r_y]

    def _resize_for_patching(
        self,
        image: "torch.Tensor",
        target_resolution: tuple,
        resample: Union["PILImageResampling", "tvF.InterpolationMode", int] | None,
        input_data_format: ChannelDimension,
    ) -> "torch.Tensor":
        """Resizes an image to a target resolution while maintaining aspect ratio."""
        new_height, new_width = get_patch_output_size(image, target_resolution, input_data_format)
        resized_image = self.resize(
            image=image,
            size=SizeDict(height=new_height, width=new_width),
            resample=resample,
        )

        return resized_image

    def _pad_for_patching(self, image: "torch.Tensor", target_resolution: tuple) -> "torch.Tensor":
        """Pad an image to a target resolution while maintaining aspect ratio, filling with the mean color."""
        new_resolution = get_patch_output_size(image, target_resolution, input_data_format=ChannelDimension.FIRST)
        padding = self._get_padding_size(new_resolution, target_resolution)
        background_color = [int(channel_mean * 255) for channel_mean in self.image_mean]
        return tvF.pad(image, padding=padding, fill=background_color)

    def _get_image_patches(
        self,
        image: "torch.Tensor",
        grid_pinpoints: list[list[int]],
        size: tuple,
        patch_size: int,
        resample: "PILImageResampling | tvF.InterpolationMode | int | None",
    ) -> list["torch.Tensor"]:
        """
        Process an image with variable resolutions by dividing it into patches. Unlike LLaVA-NeXT, the global view
        keeps the aspect ratio of the image: its longest side is resized to `size` and it is then padded to a square.
        """
        if not isinstance(grid_pinpoints, list):
            raise TypeError("grid_pinpoints must be a list of possible resolutions.")

        image_size = get_image_size(image, channel_dim=ChannelDimension.FIRST)
        best_resolution = select_best_resolution(image_size, grid_pinpoints)
        resized_image = self._resize_for_patching(
            image, best_resolution, resample=resample, input_data_format=ChannelDimension.FIRST
        )
        padded_image = self._pad_for_patching(resized_image, best_resolution)
        patches = divide_to_patches(padded_image, patch_size=patch_size)

        global_size = max(size)
        global_image = self.resize(image, size=get_global_view_size(image_size, global_size), resample=resample)
        global_image = self._pad_for_patching(global_image, (global_size, global_size))

        return [global_image] + patches

    def _pad_for_batching(
        self,
        pixel_values: list["torch.Tensor"],
    ) -> list["torch.Tensor"]:
        """Pads images on the `num_of_patches` dimension with zeros to form a batch of same number of patches."""
        max_patch = max(len(x) for x in pixel_values)
        pixel_values = [
            torch.nn.functional.pad(image, pad=[0, 0, 0, 0, 0, 0, 0, max_patch - image.shape[0]])
            for image in pixel_values
        ]

        return pixel_values

    def _preprocess(
        self,
        images: list["torch.Tensor"],
        do_resize: bool,
        size: SizeDict,
        image_grid_pinpoints: list[list[int]],
        resample: "PILImageResampling | tvF.InterpolationMode | int | None",
        do_center_crop: bool,
        crop_size: SizeDict,
        do_rescale: bool,
        rescale_factor: float,
        do_normalize: bool,
        image_mean: float | list[float] | None,
        image_std: float | list[float] | None,
        do_pad: bool | None,
        disable_grouping: bool | None,
        return_tensors: str | TensorType | None,
        **kwargs,
    ) -> BatchFeature:
        """Custom preprocessing for LLaVA-NeXT with patch processing."""
        processed_images = []
        image_sizes = []

        # Backend's resize method handles resample conversion, so we can pass it directly
        # Determine the size tuple
        if size and size.height and size.width:
            size_tuple = (size.height, size.width)
        else:
            size_tuple = (size.shortest_edge, size.shortest_edge)

        # Determine the patch size
        if crop_size and crop_size.height:
            patch_size = crop_size.height
        elif size and size.height:
            patch_size = size.height
        else:
            patch_size = size.shortest_edge

        for image in images:
            image_patches = self._get_image_patches(
                image,
                image_grid_pinpoints,
                size=size_tuple,
                patch_size=patch_size,
                resample=resample,
            )

            # Group images by size for batched processing
            processed_image_patches_grouped = {}
            grouped_image_patches, grouped_image_patches_index = group_images_by_shape(
                image_patches, disable_grouping=disable_grouping
            )
            for shape, stacked_image_patches in grouped_image_patches.items():
                if do_resize:
                    stacked_image_patches = self.resize(
                        image=stacked_image_patches,
                        size=size,
                        resample=resample,
                    )
                if do_center_crop:
                    stacked_image_patches = self.center_crop(stacked_image_patches, crop_size)
                # Fused rescale and normalize
                # Convert lists to tuples for lru_cache compatibility
                image_mean_tuple = tuple(image_mean) if isinstance(image_mean, list) else image_mean
                image_std_tuple = tuple(image_std) if isinstance(image_std, list) else image_std
                stacked_image_patches = self.rescale_and_normalize(
                    stacked_image_patches, do_rescale, rescale_factor, do_normalize, image_mean_tuple, image_std_tuple
                )
                processed_image_patches_grouped[shape] = stacked_image_patches
            processed_image_patches = reorder_images(processed_image_patches_grouped, grouped_image_patches_index)
            processed_image_patches = torch.stack(processed_image_patches, dim=0)
            processed_images.append(processed_image_patches)
            image_sizes.append(get_image_size(image, ChannelDimension.FIRST))

        if do_pad:
            processed_images = self._pad_for_batching(processed_images)

        return BatchFeature(
            data={"pixel_values": processed_images, "image_sizes": image_sizes}, tensor_type=return_tensors
        )


__all__ = ["HyperCLOVAXVisionImageProcessor"]
